        "brief": "联合国环境规划署周三发布的《2026年适应差距报告》指出，随着全球升温预计将突破1.5℃目标，发展中国家应对气候变化的资金仍严重不足，适应行动进展缓慢，气候相关损失与损害持续增加。 报告估计，到2035年，发展中国家每年需要约3050亿美元适应资金，即使实现国际公共适应资金增加至三倍的目标，也只能满足约两至三成的需求。",
