        "id": "Q09QMzHliY3n",
        "title": "COP31前瞻：今年联合国气候变化大会有哪些重要议题？",
        "brief": "如今，全球拥有比以往更多的技术和手段来应对气候变化，但仍有数百万人无法从中受益。 随着清洁能源技术以前所未有的速度发展，各国在第31届联合国气候变化大会上面临的挑战，已不再只是寻找解决方案，而是如何让所有人都有能力负担这些方案的成本。",
